RRB.load({"id":"ntpc-2025-aug-28-s1","exam":"ntpc","label":"NTPC UG CBT 1 · 28 Aug 2025 · Shift 1","time":"9:00 AM - 10:30 AM","dropped":0,"questions":[{"s":"General Awareness","q":"Which of the following Constitutional provisions can be amended by an ordinary Act of Parliament (simple majority), rather than through the special procedure under Article 368?","o":["Article 2 (Parliament may by law admit new states)","Article 356 (President’s Rule in states)","Article 368 (the Amendment procedure itself)","Article 14 (equality before law)"],"a":0,"e":"Article 4 says laws made under Articles 2 and 3 (new states, boundary changes) are not amendments under Article 368, so a simple majority suffices.","qh":"निम्नलिखित में से कौन-से संवैधानिक प्रावधानों में अनुच्छेद 368 के तहत विशेष प्रक्रिया के बजाय संसद के एक साधारण अधिनियम (साधारण बहुमत) द्वारा संशोधन किया जा सकता है?","oh":["अनुच्छेद 2 (संसद, कानून द्वारा नए राज्यों को शामिल कर सकती है)","अनुच्छेद 356 (राज्यों में राष्ट्रपति शासन)","अनुच्छेद 368 (स्वयं संशोधन प्रक्रिया)","अनुच्छेद 14 (कानून के समक्ष समानता)"],"eh":"अनुच्छेद 4 कहता है कि अनुच्छेद 2 और 3 के तहत बने कानून (नए राज्य, सीमा परिवर्तन) अनुच्छेद 368 के अंतर्गत संशोधन नहीं माने जाते, अतः साधारण बहुमत पर्याप्त है।"},{"s":"General Awareness","q":"Which shortcut key opens System Settings quickly in Windows 10/11?","o":["Alt + F4","Ctrl + Alt + Del","Windows + D","Windows + I"],"a":3,"e":"Windows + I opens Settings.","qh":"कौन-सी शॉर्टकट कुंजी (key), विंडोज 10/11 में सिस्टम सेटिंग्स (System Settings) को शीघ्रता से ओपन करती है?","oh":["Alt + F4","Ctrl + Alt + Del","Windows + D","Windows + I"],"eh":"Windows + I से Settings खुलती है।"},{"s":"General Awareness","q":"Which book written in Kannada received the 2025 International Booker Prize?","o":["The Girl with the Seven Lives","Diotima","Heart Lamp","Cascades"],"a":2,"e":"Banu Mushtaq's 'Heart Lamp', translated from Kannada by Deepa Bhasthi, won the 2025 International Booker.","qh":"कन्नड़ में लिखी गई किस पुस्तक को 2025 का अंतर्राष्ट्रीय बुकर पुरस्कार मिला?","oh":["द गर्ल विद द सेवन लाइव्स (The Girl with the Seven Lives)","दियोतिमा (Diotima)","हार्ट लैंप (Heart Lamp)","कैस्केड्स (Cascades)"],"eh":"बानू मुश्ताक की 'हार्ट लैम्प', जिसका कन्नड़ से अनुवाद दीपा भास्थी ने किया, ने 2025 का अंतर्राष्ट्रीय बुकर जीता।"},{"s":"General Awareness","q":"Through which of the following states do the Western Ghats pass?","o":["Punjab","Bihar","Tamil Nadu","Uttar Pradesh"],"a":2,"e":"The Western Ghats run through Gujarat, Maharashtra, Goa, Karnataka, Kerala and Tamil Nadu.","qh":"पश्चिमी घाट निम्नलिखित में से किस राज्य से होकर गुजरता है?","oh":["पंजाब","बिहार","तमिलनाडु","उत्तर प्रदेश"],"eh":"पश्चिमी घाट गुजरात, महाराष्ट्र, गोवा, कर्नाटक, केरल और तमिलनाडु से होकर गुजरते हैं।"},{"s":"General Awareness","q":"Which of the following agencies collaborated on India’s first Quantum Key Distribution over a Multi-Core Fibre in 2025?","o":["CSIR & ISRO","DRDO & IIT-B","C-DOT & Sterlite Technologies Ltd.","NIC & BEL"],"a":2,"e":"C-DOT and Sterlite Technologies demonstrated India's first QKD over multi-core fibre in 2025.","qh":"निम्नलिखित में से किन एजेंसियों ने वर्ष 2025 में, मल्टी-कोर फाइबर पर भारत का पहला कांटम की डिस्ट्रीब्यूशन हासिल किया?","oh":["CSIR और ISRO","DRDO और IIT-B","C-DOT और स्टरलाइट टेक्नोलॉजीज लिमिटेड","NIC और BEL"],"eh":"C-DOT और स्टरलाइट टेक्नोलॉजीज़ ने 2025 में मल्टी-कोर फाइबर पर भारत का पहला QKD प्रदर्शित किया।"},{"s":"General Awareness","q":"Article 371A of the Indian Constitution grants special provisions for the state of ____________.","o":["Punjab","Rajasthan","Nagaland","Kerala"],"a":2,"e":"Article 371A gives special provisions for Nagaland.","qh":"भारतीय संविधान का अनुच्छेद 371A ____________ राज्य के लिए विशेष प्रावधान प्रदान करता है।","oh":["पंजाब","राजस्थान","नागालैंड","केरल"],"eh":"अनुच्छेद 371A नागालैंड के लिए विशेष प्रावधान करता है।"},{"s":"General Awareness","q":"The famous slogan \"Swaraj is my birthright and I shall have it \" was given by _______.","o":["Mahatma Gandhi","Bal Gangadhar Tilak","Subhas Chandra Bose","Dadabhai Naoroji"],"a":1,"e":"Bal Gangadhar Tilak gave the slogan 'Swaraj is my birthright and I shall have it'.","qh":"प्रसिद्ध नारा \"स्वराज मेरा जन्मसिद्ध अधिकार है और मैं इसे लेकर रहूंगा\", ______ द्वारा दिया गया था।","oh":["महात्मा गांधी","बाल गंगाधर तिलक","सुभाष चंद्र बोस","दादाभाई नौरोजी"],"eh":"बाल गंगाधर तिलक ने नारा दिया 'स्वराज मेरा जन्मसिद्ध अधिकार है और मैं इसे लेकर रहूँगा'।"},{"s":"General Awareness","q":"During 1950–1990, India mainly exported which type of goods?","o":["Automobiles","Primary products","Capital goods","Crude oil"],"a":1,"e":"From 1950 to 1990 India mainly exported primary products such as tea, jute, cotton and ores.","qh":"1950-1990 के दौरान भारत द्वारा मुख्य रूप से किस प्रकार की वस्तुओं का निर्यात किया गया था?","eh":"1950 से 1990 तक भारत मुख्यतः चाय, जूट, कपास और अयस्क जैसे प्राथमिक उत्पादों का निर्यात करता था।"},{"s":"General Awareness","q":"During the Chola rule, which of the following was the land donated to Jaina institutions?","o":["Pallichchhandam","Tirunamattukkani","Shalabhoga","Vellanvagai"],"a":0,"e":"In Chola inscriptions, pallichchhandam was land donated to Jaina institutions.","qh":"चोल शासन के दौरान, निम्नलिखित में से कौन-सी भूमि जैन संस्थाओं को दान की गई थी?","oh":["पल्लीछंदम","तिरुनामट्टुक्कानी","शालाभोग","वेल्लनवागई"],"eh":"चोल अभिलेखों में पल्लिच्छंदम जैन संस्थाओं को दान की गई भूमि थी।"},{"s":"General Awareness","q":"Which of the following indicators is NOT directly included in the calculation of the Human Development Index (HDI)?","o":["Life expectancy at birth","Infant mortality rate","Mean years of schooling","Gross National Income per capita"],"a":1,"e":"HDI uses life expectancy, education (mean and expected schooling) and GNI per capita. Infant mortality isn't directly included.","qh":"निम्नलिखित में से कौन-सा संकेतक मानव विकास सूचकांक (HDI) की गणना में प्रत्यक्ष रूप से शामिल नहीं है?","eh":"HDI में जीवन प्रत्याशा, शिक्षा (औसत और अपेक्षित स्कूली वर्ष) और प्रति व्यक्ति GNI का उपयोग होता है। शिशु मृत्यु दर सीधे शामिल नहीं है।"},{"s":"General Awareness","q":"In April 2025, DOT announced funding of two specialised national testbeds for 6G R&D. One focuses on THz communication; which domain does the other explore?","o":["Visible‑light communication","Satellite backhaul","Advanced optical communication","Quantum key distribution"],"a":2,"e":"DoT funded two 6G testbeds: one for THz communication and one for advanced optical communication.","qh":"अप्रैल 2025 में, DOT ने 6G अनुसंधान एवं विकास के लिए दो विशेष राष्ट्रीय परीक्षण केंद्रों के वित्तपोषण की घोषणा की। एक THz संचार पर केंद्रित है; दूसरा किस क्षेत्र का अन्वेषण करता है?","oh":["विज़िबल-लाइट कम्युनिकेशन (Visible‑light communication)","सैटेलाइट बैकहॉल (Satellite backhaul)","एडवांस्ड ऑट्टिकल कम्युनिकेशन (Advanced optical communication)","कांटम की डिस्ट्रीब्यूशन (Quantum key distribution)"],"eh":"DoT ने दो 6G टेस्टबेड वित्तपोषित किए: एक THz संचार के लिए और एक उन्नत ऑप्टिकल संचार के लिए।"},{"s":"General Awareness","q":"Proteins are mainly responsible for which of the following?","o":["Providing quick energy","Growth and repair of tissues","Improving digestion","Enhancing memory power"],"a":1,"e":"Proteins are body-building nutrients that help growth and tissue repair.","qh":"प्रोटीन मुख्य रूप से निम्नलिखित में से किसके लिए जिम्मेदार हैं?","eh":"प्रोटीन शरीर-निर्माणकारी पोषक तत्व हैं जो वृद्धि और ऊतकों की मरम्मत में सहायक हैं।"},{"s":"General Awareness","q":"Where was the bilateral naval exercise SLINEX 24 conducted between India and Sri Lanka in December 2024?","o":["Visakhapatnam","Colombo","Kochi","Chennai"],"a":0,"e":"SLINEX-24 (December 2024) was held at Visakhapatnam.","qh":"दिसंबर 2024 में भारत और श्रीलंका के बीच द्विपक्षीय नौसैनिक अभ्यास SLINEX 24 कहाँ आयोजित किया गया था?","oh":["विशाखापत्तनम","कोलंबो","कोच्चि","चेन्नई"],"eh":"SLINEX-24 (दिसंबर 2024) विशाखापत्तनम में आयोजित हुआ।"},{"s":"General Awareness","q":"Why is canal irrigation more suitable in the northern plains of India?","o":["The rivers flow only during monsoon season.","The area suffers from very low annual rainfall.","The surface is uneven and covered with hills.","The flat land and perennial rivers support canal networks."],"a":3,"e":"Flat land and perennial Himalayan rivers make canal networks practical in the northern plains.","qh":"भारत के उत्तरी मैदानों में नहर सिंचाई अधिक उपयुक्त क्यों है?","oh":["नदियाँ केवल मानसून ऋतु में बहती हैं।","इस क्षेत्र में अत्यधिक निम्न वार्षिक वर्षा होती है।","पृष्ठ असमान होती है और पहाड़ियों से आच्छादित होती है।","सपाट भूमि और बारहमासी नदियाँ नहर नेटवर्क को सपोर्ट करती हैं।"],"eh":"समतल भूमि और हिमालय की सदानीरा नदियाँ उत्तरी मैदानों में नहर तंत्र को व्यावहारिक बनाती हैं।"},{"s":"General Awareness","q":"Which of the following pollutants is/are primarily responsible for causing acid rain?","o":["Carbon monoxide","Sulphur dioxide and nitrogen oxides","Methane","Ozone"],"a":1,"e":"SO₂ and NOₓ form sulphuric and nitric acids in the air, causing acid rain.","qh":"निम्नलिखित में से कौन-से प्रदूषक, अम्लीय वर्षा के लिए मुख्यतः जिम्मेदार हैं?","oh":["कार्बन मोनोऑक्साइड","सल्फर डाइऑक्साइड और नाइट्रोजन ऑक्साइड","मेथेन","ओजोन"],"eh":"SO₂ और NOₓ वायु में सल्फ्यूरिक और नाइट्रिक अम्ल बनाते हैं, जिससे अम्ल वर्षा होती है।"},{"s":"General Awareness","q":"Which of the following events is known as India's biggest multi-sport national competition?","o":["Khelo India Youth Games","National Games","Pro Kabaddi League","Indian Premier League"],"a":1,"e":"The National Games is India's largest national multi-sport event.","qh":"निम्नलिखित में से कौन-सा आयोजन, भारत की सबसे बड़ी बहु-खेल राष्ट्रीय प्रतियोगिता के रूप में जाना जाता है?","oh":["खेलो इंडिया यूथ गेम्स (Khelo India Youth Games)","नेशनल गेम्स (National Games)","प्रो कबड्डी लीग (Pro Kabaddi League)","इंडियन प्रीमियर लीग (Indian Premier League)"],"eh":"राष्ट्रीय खेल भारत का सबसे बड़ा राष्ट्रीय बहु-खेल आयोजन है।"},{"s":"General Awareness","q":"Which acid and its salts are widely used as food preservatives to prevent the growth of mould, yeast and fungi?","o":["Perchloric acid","Boric Acid","Malic acid","Sorbic acid"],"a":3,"e":"Sorbic acid and its salts (sorbates) are common anti-fungal food preservatives.","qh":"निम्नलिखित में से कौन-सा अम्ल और इसके लवण, फफूंद, खमीर और कवक की वृद्धि को रोकने के लिए व्यापक रूप से खाद्य परिरक्षक के रूप में प्रयुक्त किए जाते हैं?","oh":["परक्लोरिक अम्ल","बोरिक अम्ल","मैलिक अम्ल","सोर्बिक अम्ल"],"eh":"सॉर्बिक अम्ल और उसके लवण (सॉर्बेट) सामान्य कवकरोधी खाद्य परिरक्षक हैं।"},{"s":"General Awareness","q":"Who among the following has been appointed as the International Trade Negotiator by China in April 2025?","o":["Li Chenggang","Jiang Zaidong","Xu Feihong","Wang Shouwen"],"a":0,"e":"Li Chenggang was appointed China's international trade negotiator in April 2025.","qh":"अप्रैल 2025 में, चीन द्वारा निम्नलिखित में से किसे अंतर्राष्ट्रीय व्यापार वार्ताकार नियुक्त किया गया है?","oh":["ली चेंगगांग (Li Chenggang)","जियांग जैदोंग (Jiang Zaidong)","जू फेइहोंग (Xu Feihong)","वांग शॉवेन (Wang Shouwen)"],"eh":"ली चेंगगांग को अप्रैल 2025 में चीन का अंतर्राष्ट्रीय व्यापार वार्ताकार नियुक्त किया गया।"},{"s":"General Awareness","q":"Which Indian athlete set a new national record in the 200m sprint at the 2025 Asian Athletics Championships?","o":["Animesh Kujur","Gurindervir Singh","Amlan Borgohain","Amiya Mallick"],"a":0,"e":"Animesh Kujur set a 200m national record (20.32 s) at the 2025 Asian Athletics Championships.","qh":"2025 एशियाई एथलेटिक्स चैंपियनशिप में किस भारतीय एथलीट ने 200m स्प्रिंट (sprint) में नया राष्ट्रीय रिकॉर्ड बनाया?","oh":["अनिमेष कुजूर","गुरिंदरवीर सिंह","अमलान बोरगोहेन","अमिया मलिक"],"eh":"अनिमेष कुजूर ने 2025 एशियाई एथलेटिक्स चैंपियनशिप में 200m का राष्ट्रीय रिकॉर्ड (20.32 s) बनाया।"},{"s":"General Awareness","q":"What happens when you double-click an icon on the desktop?","o":["It gets deleted.","It goes to the Taskbar.","It opens the application or file.","It minimizes the window."],"a":2,"e":"Double-clicking a desktop icon opens the file or application.","qh":"जब आप डेस्कटॉप पर किसी आइकन पर डबल-क्लिक करते हैं, तो क्या होता है?","eh":"डेस्कटॉप आइकन पर डबल-क्लिक करने से फ़ाइल या एप्लिकेशन खुलता है।"},{"s":"General Awareness","q":"Which leader founded the Servants of India Society to train Indians for national service and political awareness?","o":["BR Ambedkar","Motilal Nehru","Bal Gangadhar Tilak","Gopal Krishna Gokhale"],"a":3,"e":"Gopal Krishna Gokhale founded the Servants of India Society in 1905.","qh":"किस नेता ने भारतीयों को राष्ट्रीय सेवा और राजनीतिक जागरूकता के लिए प्रशिक्षित करने हेतु सर्वेंट्स ऑफ इंडिया सोसाइटी की स्थापना की?","oh":["बी.आर. अंबेडकर","मोतीलाल नेहरू","बाल गंगाधर तिलक","गोपाल कृष्ण गोखले"],"eh":"गोपाल कृष्ण गोखले ने 1905 में सर्वेंट्स ऑफ इंडिया सोसाइटी की स्थापना की।"},{"s":"General Awareness","q":"Chilika Lake and Pulicat Lake are located in which of the following?","o":["West Coast of India","Malabar Coast","Konkan Coast","East Coast of India"],"a":3,"e":"Chilika (Odisha) and Pulicat (AP/TN) are lagoons on the east coast.","qh":"चिलिका झील और पुलिकट झील निम्नलिखित में से कहां स्थित हैं?","eh":"चिल्का (ओडिशा) और पुलिकट (आंध्र प्रदेश/तमिलनाडु) पूर्वी तट पर स्थित लैगून हैं।"},{"s":"General Awareness","q":"Which of the following sectors has been classified as infrastructure by the Government of India for improved financing access?","o":["Warehousing","Education","Apparel","Retail"],"a":0,"e":"Warehousing is on the Harmonised Master List of infrastructure sub-sectors.","qh":"निम्नलिखित में से किस क्षेत्र को भारत सरकार द्वारा बेहतर वित्तपोषण पहुंच के लिए अवसंरचना के रूप में वर्गीकृत किया गया है?","oh":["माल भण्डारण (Warehousing)","शिक्षा (Education)","परिधान (Apparel)","रिटेल (Retail)"],"eh":"भंडारण (वेयरहाउसिंग) अवसंरचना उप-क्षेत्रों की सुसंगत मास्टर सूची में शामिल है।"},{"s":"General Awareness","q":"Who among the following threw 19.59 m to bag Silver medal in Shot Put at Asian U-18 Athletics Championship in April 2025?","o":["Anuragh G","VS Anupriya","Vidhi","Nishchay"],"a":3,"e":"Nishchay won shot put silver with 19.59 m at the 2025 Asian U-18 Championships.","qh":"निम्नलिखित में से किसने, अप्रैल 2025 में एशियाई अंडर-18 एथलेटिक्स चैम्पियनशिप में शॉट पुट में 19.59 मीटर थ्रो करके रजत पदक जीता?","oh":["अनुराग जी","वीएस अनुप्रिया","विधि","निश्चय"],"eh":"निश्चय ने 2025 एशियाई U-18 चैंपियनशिप में 19.59 m के साथ गोला फेंक में रजत जीता।"},{"s":"General Awareness","q":"What was the capital of Awadh when it was established in 1722?","o":["Faizabad","Bareilly","Gorakhpur","Fatehpur"],"a":0,"e":"Awadh's early capital under Saadat Khan (1722) was Faizabad. It later moved to Lucknow.","qh":"1722 में, अवध की स्थापना के समय इसकी राजधानी क्या थी?","oh":["फैजाबाद","बरेली","गोरखपुर","फतेहपुर"],"eh":"सआदत खान (1722) के अधीन अवध की प्रारंभिक राजधानी फैजाबाद थी। बाद में यह लखनऊ स्थानांतरित हुई।"},{"s":"General Awareness","q":"Which organelle is responsible for photosynthesis in plants?","o":["Mitochondria","Chloroplast","Leucoplast","Chromoplast"],"a":1,"e":"Chloroplasts contain chlorophyll and carry out photosynthesis.","qh":"पौधों में प्रकाश संश्लेषण के लिए कौन-सा अंग जिम्मेदार है?","oh":["माइटोकॉन्ड्रिया (Mitochondria)","क्लोरोप्लास्ट (Chloroplast)","ल्यूकोप्लास्ट (Leucoplast)","क्रोमोप्लास्ट (Chromoplast)"],"eh":"हरितलवक (क्लोरोप्लास्ट) में क्लोरोफिल होता है और ये प्रकाश संश्लेषण करते हैं।"},{"s":"General Awareness","q":"Why does a diverse society need a constitution?","o":["To impose religious uniformity","To eliminate all differences","To provide basic rules for coordination and assurance","To allow rulers to dominate others"],"a":2,"e":"A constitution gives a diverse society basic rules that allow coordination and assure every group.","qh":"विविधतापूर्ण समाज को संविधान की आवश्यकता क्यों है?","eh":"संविधान विविध समाज को बुनियादी नियम देता है, जिनसे समन्वय संभव होता है और हर समूह को आश्वासन मिलता है।"},{"s":"General Awareness","q":"Software Technology Parks of India (STPI) is a premier S&T organisation under which of the following ministries of the Government of India?","o":["Ministry of Home Affairs","Ministry of Electronics and Information Technology (MeitY)","Ministry of Communications","Ministry of Science and Technology"],"a":1,"e":"STPI is a society under the Ministry of Electronics and IT (MeitY).","qh":"सॉप्टवेयर टेक्नोलॉजी पार्क्स ऑफ इंडिया (STPI), भारत सरकार के निम्नलिखित में से किस मंत्रालय के तहत एक प्रिमियर एस एंड टी (premier S&T) संगठन है?","eh":"STPI इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय (MeitY) के अधीन एक सोसाइटी है।"},{"s":"General Awareness","q":"In which of the following years was Ishwar Chandra Vidyasagar born, who is remembered for his efforts in widow remarriage and the abolition of polygamy in Hindu society?","o":["1812","1820","1849","1835"],"a":1,"e":"Ishwar Chandra Vidyasagar was born in 1820.","qh":"ईश्वर चंद्र विद्यासागर का जन्म निम्नलिखित में से किस वर्ष हुआ था, जिन्हें हिंदू समाज में, विधवा पुनर्विवाह करवाने और बहुविवाह के उन्मूलन के प्रयासों के लिए याद किया जाता है?","oh":["1812","1820","1849","1835"],"eh":"ईश्वरचंद्र विद्यासागर का जन्म 1820 में हुआ।"},{"s":"General Awareness","q":"Which of the following options correctly describes the scope of judicial review under the Constitution of India?","o":["Only the Supreme Court can declare laws unconstitutional.","Judicial review is explicitly mentioned in the Constitution (Article 13).","Both, Supreme Court and High Courts can strike down unconstitutional laws.","Courts can review any law only after approval by the Parliament."],"a":2,"e":"Both the Supreme Court and the High Courts can declare laws unconstitutional (judicial review).","qh":"निम्नलिखित में से कौन-सा विकल्प भारत के संविधान के अंतर्गत न्यायिक समीक्षा के दायरे का सही वर्णन करता है?","eh":"सर्वोच्च न्यायालय और उच्च न्यायालय दोनों कानूनों को असंवैधानिक घोषित कर सकते हैं (न्यायिक पुनर्विलोकन)।"},{"s":"General Awareness","q":"On May 27, 2025, the Rajasthan High Court issued a directive regarding FIRs and financial transactions. What was one of the key mandates?","o":["All FIRs must be approved by a magistrate before registration.","All property transactions must be conducted through digital payments.","FIRs can only be filed for criminal offenses, not civil disputes.","Courts must report cash transactions over ₹2 lakh to the Income Tax Department."],"a":3,"e":"The Rajasthan HC told courts to report cash transactions above ₹2 lakh to the Income Tax Department.","qh":"27 मई, 2025 को राजस्थान उच्च न्यायालय ने FIR और वित्तीय लेनदेन के संबंध में एक निर्देश जारी किया। इसका एक प्रमुख अधिदेश क्या था?","eh":"राजस्थान उच्च न्यायालय ने अदालतों को ₹2 लाख से अधिक के नकद लेनदेन की सूचना आयकर विभाग को देने को कहा।"},{"s":"General Awareness","q":"Which Article of the Indian Constitution states that a person who had voluntarily acquired the citizenship of a foreign State shall NOT be considered a citizen of India at the commencement of the Constitution under Articles 5, 6, or 8?","o":["Article 9","Article 10","Article 12","Article 11"],"a":0,"e":"Article 9: anyone who voluntarily acquired foreign citizenship is not an Indian citizen.","qh":"भारतीय संविधान के किस अनुच्छेद में यह चर्चा है कि यदि कोई व्यक्ति जिसने स्वेच्छा से किसी विदेशी राज्य की नागरिकता प्राप्त कर ली है, उसे संविधान के प्रारंभ में अनुच्छेद 5, 6 या 8 के आधार पर भारत का नागरिक नहीं माना जाएगा?","oh":["अनुच्छेद 9","अनुच्छेद 10","अनुच्छेद 12","अनुच्छेद 11"],"eh":"अनुच्छेद 9: जिसने स्वेच्छा से विदेशी नागरिकता प्राप्त कर ली है, वह भारतीय नागरिक नहीं है।"},{"s":"General Awareness","q":"Which Indian State/Union Territory inaugurated modern sports facilities, including chess centres and a snooker hall, in 2025?","o":["Maharashtra","Punjab","Chandigarh","Andaman and Nicobar"],"a":2,"e":"Chandigarh opened modern sports facilities, including chess centres and a snooker hall, in 2025.","qh":"2025 में किस भारतीय राज्य/केंद्र शासित प्रदेश ने चेस सेंटर और स्नूकर हॉल (chess centres and a snooker hall) सहित आधुनिक खेल सुविधाओं का उद्घाटन किया?","oh":["महाराष्ट्र","पंजाब","चंडीगढ़","अंडमान एवं निकोबार"],"eh":"चंडीगढ़ ने 2025 में शतरंज केंद्रों और स्नूकर हॉल सहित आधुनिक खेल सुविधाएँ शुरू कीं।"},{"s":"General Awareness","q":"Which special representation in the Lok Sabha and State Assemblies was discontinued by the 104th Constitutional Amendment Act, 2020?","o":["Reservation for Women","SC/ST Reservation","Anglo-Indian Reservation","OBC Reservation"],"a":2,"e":"The 104th Amendment (2020) ended Anglo-Indian nomination to the Lok Sabha and Assemblies.","qh":"वें 104 संविधान संशोधन अधिनियम, 2020 द्वारा लोकसभा और राज्य विधानसभाओं में कौन-सा विशेष प्रतिनिधित्व समाप्त कर दिया गया?","oh":["महिलाओं के लिए आरक्षण","SC/ST आरक्षण","एंग्लो-इंडियन आरक्षण","OBC आरक्षण"],"eh":"104वें संशोधन (2020) ने लोकसभा और विधानसभाओं में आंग्ल-भारतीयों का मनोनयन समाप्त कर दिया।"},{"s":"General Awareness","q":"Which force will get the Ashwini radar system under the ₹2,906-crore deal signed in March 2025?","o":["Indian Navy","Indian Army","Indian Air Force","Indian Coast Guard"],"a":2,"e":"The ₹2,906 crore Ashwini low-level radar deal (March 2025) was for the Indian Air Force.","qh":"मार्च 2025 में हस्ताक्षरित ₹2,906 करोड़ के सौदे के तहत किस बल (force) को अश्विनी रडार प्रणाली मिलेगी?","eh":"₹2,906 करोड़ का अश्विनी लो-लेवल रडार सौदा (मार्च 2025) भारतीय वायु सेना के लिए था।"},{"s":"General Awareness","q":"In the K. Umadevi v. Government of Tamil Nadu case, 2022, the Supreme Court granted maternity benefits for the third child under the Maternity Benefit (Amendment) Act, 2017, stating it is a constitutional right. Which fundamental right did the Court link this benefit to?","o":["Right to Education under Article 21A","Right to Life under Article 21","Right to Equality under Article 14","Right against Exploitation under Article 23"],"a":1,"e":"The SC tied maternity benefit to the right to life and dignity under Article 21.","qh":"2022 में, के. उमादेवी बनाम तमिलनाडु सरकार मामले में सवोंच्च न्यायालय ने प्रसूति प्रसुविधा (संशोधन) अधिनियम, 2017 के तहत, तीसरे बच्चे के लिए प्रसूति प्रसुविधा प्रदान की और कहा कि यह एक संवैधानिक अधिकार है। न्यायालय ने इस प्रसुविधा को किस मौलिक अधिकार से जोड़ा?","oh":["अनुच्छेद 21A के तहत शिक्षा का अधिकार","अनुच्छेद 21 के तहत जीवन का अधिकार","अनुच्छेद 14 के तहत समानता का अधिकार","अनुच्छेद 23 के तहत शोषण के विरुद्ध अधिकार"],"eh":"सर्वोच्च न्यायालय ने मातृत्व लाभ को अनुच्छेद 21 के तहत जीवन और गरिमा के अधिकार से जोड़ा।"},{"s":"General Awareness","q":"Colonial policies led to the commercialisation of agriculture. Which of the following crops was encouraged for export during British rule?","o":["Maize","Indigo","Barley","Pulses"],"a":1,"e":"The British pushed cash crops such as indigo for export.","qh":"उपनिवेशी नीतियों ने कृषि के वाणिज्यीकरण को बढ़ावा दिया। ब्रिटिश शासन के दौरान निम्नलिखित में से किस फसल को निर्यात के लिए प्रोत्साहित किया गया था?","eh":"अंग्रेज़ों ने निर्यात के लिए नील जैसी नकदी फसलों को बढ़ावा दिया।"},{"s":"General Awareness","q":"Which of the following traditional folk theatre forms is famous in Maharashtra?","o":["Tamasha","Yakshagana","Nautanki","Bhavai"],"a":0,"e":"Tamasha is Maharashtra's folk theatre. Yakshagana is from Karnataka and Bhavai from Gujarat.","qh":"निम्नलिखित में से कौन-सा, पारंपरिक लोक रंगमंच रूप महाराष्ट्र में प्रसिद्ध है?","oh":["तमाशा","यक्षगान","नौटंकी","भवाई"],"eh":"तमाशा महाराष्ट्र का लोक रंगमंच है। यक्षगान कर्नाटक का और भवाई गुजरात का है।"},{"s":"General Awareness","q":"The neighbouring countries Peru and Chile are located in which continent?","o":["Europe","Africa","South America","Asia"],"a":2,"e":"Peru and Chile are in South America.","qh":"पड़ोसी देश पेरू और चिली, किस महाद्वीप में स्थित हैं?","oh":["यूरोप","अफ्रीका","दक्षिण अमेरिका","एशिया"],"eh":"पेरू और चिली दक्षिण अमेरिका में हैं।"},{"s":"General Awareness","q":"PM Modi’s review of NTEP in May 2025 urged volunteers called _____________ to adopt AI tools for patient follow‑up.","o":["Nikshay Mitras","Swasth Sanginis","TB Mitra","Arogya Sahayaks"],"a":0,"e":"Ni-kshay Mitras are TB support volunteers under NTEP.","qh":"मई 2025 में पीएम मोदी की NTEP की समीक्षा में _____________ नामक स्वयंसेवकों से रोगी अनुवर्ती के लिए AI उपकरण अपनाने का आग्रह किया गया।","oh":["निक्षय मित्र (Nikshay Mitras)","स्वस्थ संगिनी (Swasth Sanginis)","टीबी मित्र (TB Mitra)","आरोग्य सहायक (Arogya Sahayaks)"],"eh":"नि-क्षय मित्र NTEP के तहत TB सहायता स्वयंसेवक हैं।"},{"s":"Mathematics","q":"A company earns a profit (in ₹) that is distributed among the company's three partners in the ratio of 12 : 3 : 14. If the difference between the smallest and the largest shares is ₹61,699, the total profit (in ₹) of the company is:","o":["1,62,661","1,62,566","1,62,581","1,62,673"],"a":0,"e":"14 − 3 = 11 parts = 61699, so 1 part = 5609. Total = 29 × 5609 = ₹1,62,661.","qh":"किसी कंपनी द्वारा अर्जित लाभ (₹ में) को कंपनी के तीन साझेदारों के बीच 12 : 3 : 14 के अनुपात में बांट दिया जाता है। यदि सबसे छोटे और सबसे बड़े हिस्से में अंतर ₹61,699 है, तो कंपनी का कुल लाभ (₹ में) ज्ञात कीजिए।","oh":["1,62,661","1,62,566","1,62,581","1,62,673"],"eh":"14 − 3 = 11 भाग = 61699, अतः 1 भाग = 5609। कुल = 29 × 5609 = ₹1,62,661।"},{"s":"Mathematics","q":"₹21,300 were divided among A, B and C, such that 2 times the share of A = 4 times the share of B = 7 times the share of C. Find the share of A.","o":["₹11,868","₹11,919","₹12,099","₹11,928"],"a":3,"e":"A : B : C = 1/2 : 1/4 : 1/7 = 14 : 7 : 4, so A = 21300 × 14/25 = ₹11,928.","qh":"₹21,300 को A, B और C के बीच इस प्रकार विभाजित किया गया कि A के हिस्से का 2 गुना = B के हिस्से का 4 गुना = C के हिस्से का 7 गुना है। A का हिस्सा ज्ञात कीजिए।","oh":["₹11,868","₹11,919","₹12,099","₹11,928"],"eh":"A : B : C = 1/2 : 1/4 : 1/7 = 14 : 7 : 4, अतः A = 21300 × 14/25 = ₹11,928।"},{"s":"Mathematics","q":"A number, when increased by 60%, gives 3640. The number is:","o":["4550","1137.5","6825","2275"],"a":3,"e":"1.6x = 3640, so x = 2275.","qh":"किसी संख्या में 60% वृद्धि करने पर 3640 प्राप्त होता है। संख्या ज्ञात कीजिए।","oh":["4550","1137.5","6825","2275"],"eh":"1.6x = 3640, अतः x = 2275।"},{"s":"Mathematics","q":"A shopkeeper offers the following four discount schemes to his customers for the purchase of articles in his shop. (i) Buy 5 and get 3 free (ii) Buy 6 and get 3 free (iii) Buy 20 and get 5 free (iv) Buy 8 and get 6 free Which scheme is the most beneficial to the customers?","o":["(ii)","(i)","(iv)","(iii)"],"a":2,"e":"Share of items free: (i) 3/8 = 37.5%, (ii) 33.3%, (iii) 20%, (iv) 6/14 = 42.9%. Scheme (iv) is best.","qh":"एक दुकानदार अपने ग्राहकों को अपनी दुकान में वस्तुओं की खरीद के लिए निम्नलिखित चार छूट योजनाएं प्रदान करता है। (i) 5 खरीदें और 3 मुफ़्त पाएं (ii) 6 खरीदें और 3 मुफ़्त पाएं (iii) 20 खरीदें और 5 मुफ़्त पाएं (iv) 8 खरीदें और 6 मुफ़्त पाएं ग्राहकों के लिए कौन-सी योजना सर्वाधिक लाभदायक है?","oh":["(ii)","(i)","(iv)","(iii)"],"eh":"मुफ्त वस्तुओं का अनुपात: (i) 3/8 = 37.5%, (ii) 33.3%, (iii) 20%, (iv) 6/14 = 42.9%। योजना (iv) सबसे अच्छी है।"},{"s":"Mathematics","q":"The sum of the squares of two consecutive even natural numbers is 452. The sum of the numbers is:","o":["48","30","44","26"],"a":1,"e":"n² + (n + 2)² = 452 gives n = 14. The numbers are 14 and 16, summing to 30.","qh":"दो क्रमागत सम प्राकृत संख्याओं के वर्गों का योग 452 है। संख्याओं का योग ज्ञात कीजिए।","oh":["48","30","44","26"],"eh":"n² + (n + 2)² = 452 से n = 14। संख्याएँ 14 और 16 हैं, योग 30।"},{"s":"Mathematics","q":"Evaluate: (-9) - (-60) ÷ (-12) + (-2) × 9","o":["-34","-32","-31","-35"],"a":1,"e":"−9 − 5 + (−18) = −32, since (−60) ÷ (−12) = 5.","qh":"निम्नलिखित का मान ज्ञात कीजिए: (-9) - (-60) ÷ (-12) + (-2) × 9","oh":["-34","-32","-31","-35"],"eh":"−9 − 5 + (−18) = −32, क्योंकि (−60) ÷ (−12) = 5।"},{"s":"Mathematics","q":"The LCM of the numbers 8.6 and 0.12 is:","o":["2.58","258","25.8","0.258"],"a":2,"e":"LCM(860, 12) = 2580, then divide by 100: 25.8.","qh":"संख्याओं 8.6 और 0.12 का लघुत्तम समापवर्त्य (LCM) ज्ञात कीजिए।","oh":["2.58","258","25.8","0.258"],"eh":"LCM(860, 12) = 2580, फिर 100 से भाग दें: 25.8।"},{"s":"Mathematics","q":"Sapna invested ₹20,000 on simple interest, partly at 12% per annum and partly at 13% per annum. If she earns equal interests from the two investments after 7 years, then find the sum invested at 12% per annum (in ₹).","o":["10,398","10,403","10,400","10,399"],"a":2,"e":"12x = 13(20000 − x), so 25x = 260000 and x = ₹10,400.","qh":"सपना ने ₹20,000 की धनराशि में से कुछ धनराशि 12% वार्षिक साधारण ब्याज की दर से और शेष धनराशि 13% वार्षिक साधारण ब्याज की दर से निवेश की। यदि उसे 7 वर्षों के बाद दोनों निवेशों से बराबर ब्याज प्राप्त होता है, तो 12% वार्षिक साधारण ब्याज की दर से निवेश की गई धनराशि (₹ में) ज्ञात कीजिए।","oh":["10,398","10,403","10,400","10,399"],"eh":"12x = 13(20000 − x), अतः 25x = 260000 और x = ₹10,400।"},{"s":"Mathematics","q":"The diameter of a sphere is 12 cm. Find its volume.","o":["144π cm³","288π cm³","576π cm³","192π cm³"],"a":1,"e":"r = 6, so V = 4/3 π × 216 = 288π cm³.","qh":"एक गोले का व्यास 12 cm है। इसका आयतन ज्ञात कीजिए।","oh":["144π cm³","288π cm³","576π cm³","192π cm³"],"eh":"r = 6, अतः V = 4/3 π × 216 = 288π cm³।"},{"s":"Mathematics","q":"","o":["−98x − 111","98x − 111","−98x + 111","98x + 111"],"a":2,"img":"data/img/ntpc-2025-aug-28-s1/010ma-q0.png","e":"2(7/2 x² − 28x + 17) − 7(x² + 6x − 11) = 7x² − 56x + 34 − 7x² − 42x + 77 = −98x + 111.","eh":"2(7/2 x² − 28x + 17) − 7(x² + 6x − 11) = 7x² − 56x + 34 − 7x² − 42x + 77 = −98x + 111।"},{"s":"Mathematics","q":"A trader claims to sell flour at a profit of 44%, but also dishonestly uses a weight which is 10% less than what is mentioned on it. Find the total percentage of profit earned by the trader. (Round off the answer to the nearest whole number.)","o":["","","",""],"a":3,"oi":["data/img/ntpc-2025-aug-28-s1/011ma-o1.png","data/img/ntpc-2025-aug-28-s1/011ma-o2.png","data/img/ntpc-2025-aug-28-s1/011ma-o3.png","data/img/ntpc-2025-aug-28-s1/011ma-o4.png"],"e":"Profit = 1.44/0.90 − 1 = 0.60, i.e. 60%.","qh":"एक व्यापारी 44% लाभ पर आटा बेचने का दावा करता है, लेकिन बेईमानी से उस बाट का इस्तेमाल करता है जो उस पर उल्लिखित वजन से 10% कम है। व्यापारी द्वारा अर्जित लाभ का कुल प्रतिशत ज्ञात कीजिए। (उत्तर को निकटतम पूर्ण संख्या में पूणाेंकित कीजिए।)","eh":"लाभ = 1.44/0.90 − 1 = 0.60, अर्थात 60%।"},{"s":"Mathematics","q":"I bought two bicycles for ₹1,200. I sold the first one at a loss of 9% and the second at a gain of 27%. If, on the whole I made neither a loss nor a gain, find the cost price (in ₹) of the first bicycle.","o":["920","924","884","900"],"a":3,"e":"−0.09x + 0.27(1200 − x) = 0, so 0.36x = 324 and x = ₹900.","qh":"मैंने ₹1,200 में दो साइकिलें खरीदीं। मैंने पहली साइकिल 9% की हानि पर और दूसरी साइकिल 27% के लाभ पर बेची। यदि कुल मिलाकर मुझे न तो हानि हुई और न ही लाभ हुआ, तो पहली साइकिल का क्रय मूल्य (₹ में) ज्ञात कीजिए।","oh":["920","924","884","900"],"eh":"−0.09x + 0.27(1200 − x) = 0, अतः 0.36x = 324 और x = ₹900।"},{"s":"Mathematics","q":"A chair was sold for ₹4,600 after giving two successive discounts of 12% and 9%. What is the marked price? (Rounded up to two decimal places.)","o":["₹8,008.39","₹7,820.12","₹7,948.74","₹5,744.26"],"a":3,"e":"MP = 4600 ÷ (0.88 × 0.91) = 4600 ÷ 0.8008 = ₹5,744.26.","qh":"एक कुर्सी को 12% और 9% की दो क्रमिक छूट देने के बाद ₹4,600 में बेचा गया। अंकित मूल्य कितना है? (दो दशमलव स्थान तक पूणाेंकित)","oh":["₹8,008.39","₹7,820.12","₹7,948.74","₹5,744.26"],"eh":"अंकित मूल्य = 4600 ÷ (0.88 × 0.91) = 4600 ÷ 0.8008 = ₹5,744.26।"},{"s":"Mathematics","q":"If the sum of all interior angles of a regular polygon is 28 right angles, then its number of sides is:","o":["15","14","13","16"],"a":3,"e":"(n − 2) × 180° = 28 × 90°, so n − 2 = 14 and n = 16.","qh":"यदि किसी सम बहुभुज के सभी अंतः कोणों का योग 28 समकोण है, तो उसकी भुजाओं की संख्या कितनी होगी?","oh":["15","14","13","16"],"eh":"(n − 2) × 180° = 28 × 90°, अतः n − 2 = 14 और n = 16।"},{"s":"Mathematics","q":"A sum of money triples itself at a certain rate of compound interest in 16 years. In how many years will it amount to 9 times of itself?","o":["29 years","26 years","27 years","32 years"],"a":3,"e":"3× in 16 years means 9× = 3² in 32 years.","qh":"एक धनराशि चक्रवृद्धि ब्याज की एक निश्चित दर पर 16 वर्षों में तीन गुनी हो जाती है। कितने वर्षों में यह धनराशि 9 गुना हो जाएगी?","oh":["29 वर्ष","26 वर्ष","27 वर्ष","32 वर्ष"],"eh":"16 वर्षों में 3 गुना का अर्थ है 32 वर्षों में 9 गुना = 3²।"},{"s":"Mathematics","q":"A train that has a length of 150 m overtakes a man moving at a speed of 9 km/hr (in the same direction) in 36 seconds. How much time (in seconds) will it take this train to completely cross another train that is 185 m long, moving in the opposite direction at a speed of 43 km/hr?","o":["35","18","23","12"],"a":1,"e":"150/36 = v − 2.5 m/s, so v = 20/3 m/s = 24 km/h. Crossing: 335 m at (24 + 43) km/h = 18.61 m/s gives 18 s.","qh":"150 m लंबी एक ट्रेन, 9 km/hr की चाल से (समान दिशा में) चल रहे एक व्यक्ति को 36 सेकंड में पार कर लेती है। इस ट्रेन को विपरीत दिशा में 43 km/hr की चाल से चल रही 185 m लंबी एक अन्य ट्रेन को पूरी तरह से पार करने में कितना समय (सेकंड में) लगेगा?","oh":["35","18","23","12"],"eh":"150/36 = v − 2.5 m/s, अतः v = 20/3 m/s = 24 km/h। पार करना: 335 m, (24 + 43) km/h = 18.61 m/s पर 18 s।"},{"s":"Mathematics","q":"The marks scored by 10 students are given below. 11, 11, 14, 12, 20, 19, 16, 18, 11, 12 The mode of the data is:","o":["12","14","10","11"],"a":3,"e":"11 appears 3 times, more than any other value.","qh":"10 विद्यार्थियों द्वारा प्राप्त अंक नीचे दिए गए हैं। 11, 11, 14, 12, 20, 19, 16, 18, 11, 12 आँकड़ों का बहुलक ज्ञात कीजिए।","oh":["12","14","10","11 3"],"eh":"11 तीन बार आता है, जो किसी भी अन्य मान से अधिक है।"},{"s":"Mathematics","q":"If 3 times Mary’s present age is 27 years more than 9 times Diya's present age, and 4 times Diya's present age is 7 years less than Mary's present age, then what is the difference (in years) between the ages of Mary and Diya?","o":["13","10","8","17"],"a":0,"e":"3M = 9D + 27 and M = 4D + 7, so D = 2 and M = 15. Difference = 13.","qh":"यदि मैरी की वर्तमान आयु का 3 गुना, दीया की वर्तमान आयु के 9 गुने से 27 वर्ष अधिक है, और दीया की वर्तमान आयु का 4 गुना, मैरी की वर्तमान आयु से 7 वर्ष कम है, तो मैरी और दीया की आयु के बीच का अंतर (वर्षों में) कितना है?","oh":["13","10","8","17"],"eh":"3M = 9D + 27 और M = 4D + 7, अतः D = 2 और M = 15। अंतर = 13।"},{"s":"Mathematics","q":"","o":["","","",""],"a":2,"img":"data/img/ntpc-2025-aug-28-s1/019ma-q0.png","oi":["data/img/ntpc-2025-aug-28-s1/019ma-o1.png","data/img/ntpc-2025-aug-28-s1/019ma-o2.png","data/img/ntpc-2025-aug-28-s1/019ma-o3.png","data/img/ntpc-2025-aug-28-s1/019ma-o4.png"],"e":"(1 + sin θ)(sec θ − tan θ) = (1 − sin²θ)/cos θ = cos θ, and sec θ × cos θ = 1.","eh":"(1 + sin θ)(sec θ − tan θ) = (1 − sin²θ)/cos θ = cos θ, और sec θ × cos θ = 1।"},{"s":"Mathematics","q":"A man goes to Lucknow from Kanpur at a speed of 18 km/hr and returns to Kanpur at speed of 36 km/hr, through the same route. What is his average speed (in km/hr) of the entire journey?","o":["18","24","22","27"],"a":1,"e":"Average = 2 × 18 × 36/(18 + 36) = 24 km/h.","qh":"एक व्यक्ति 18 km/hr की चाल से कानपुर से लखनऊ जाता है और उसी मार्ग से 36 km/hr की चाल से कानपुर वापस आता है। संपूर्ण यात्रा में उसकी औसत चाल (km/hr में) ज्ञात कीजिए।","oh":["18","24","22","27"],"eh":"औसत = 2 × 18 × 36/(18 + 36) = 24 km/h।"},{"s":"Mathematics","q":"The average of first 164 even numbers is","o":["165","164.5","166","165.5"],"a":0,"e":"The average of the first n even numbers = n + 1 = 165.","qh":"प्रथम 164 सम संख्याओं का औसत ज्ञात कीजिए।","oh":["165","164.5","166","165.5"],"eh":"पहली n सम संख्याओं का औसत = n + 1 = 165।"},{"s":"Mathematics","q":"","o":["","","",""],"a":2,"img":"data/img/ntpc-2025-aug-28-s1/022ma-q0.png","oi":["data/img/ntpc-2025-aug-28-s1/022ma-o1.png","data/img/ntpc-2025-aug-28-s1/022ma-o2.png","data/img/ntpc-2025-aug-28-s1/022ma-o3.png","data/img/ntpc-2025-aug-28-s1/022ma-o4.png"],"e":"P and Q each fill the tank in 36 h. In 2 h they fill 1/9, which R empties in 4 h, so R = 1/36 per hour. P + Q − R = 1/36, i.e. 36 hours.","eh":"P और Q प्रत्येक टंकी को 36 घंटे में भरते हैं। 2 घंटे में वे 1/9 भरते हैं, जिसे R 4 घंटे में खाली करता है, अतः R = 1/36 प्रति घंटा। P + Q − R = 1/36, अर्थात 36 घंटे।"},{"s":"Mathematics","q":"If 51% of first number is equal to six-sevenths of second number, what is the ratio of first number to the second number?","o":["205 : 116","195 : 114","199 : 124","200 : 119"],"a":3,"e":"0.51a = (6/7)b, so a/b = 6/3.57 = 200/119.","qh":"यदि पहली संख्या का 51%, दूसरी संख्या के वें भाग के बराबर है, तो पहली संख्या का दूसरी संख्या से अनुपात कितना है?","oh":["205 : 116","195 : 114","199 : 124","200 : 119"],"eh":"0.51a = (6/7)b, अतः a/b = 6/3.57 = 200/119।"},{"s":"Mathematics","q":"A can lay railway track between two given stations in 19 days and B can do the same job in 11 days. With the help of C, they did the job in 2 days only. Then, C alone can do the job in","o":["","","",""],"a":1,"oi":["data/img/ntpc-2025-aug-28-s1/024ma-o1.png","data/img/ntpc-2025-aug-28-s1/024ma-o2.png","data/img/ntpc-2025-aug-28-s1/024ma-o3.png","data/img/ntpc-2025-aug-28-s1/024ma-o4.png"],"e":"C = 1/2 − 1/19 − 1/11 = 149/418 per day, so C alone takes 418/149 = 2 120/149 days.","qh":"A दो स्टेशनों के बीच रेलवे ट्रैक को 19 दिनों में बिछा सकता है और B उसी कार्य को 11 दिनों में पूरा कर सकता है। C की सहायता से, उन्होंने यह कार्य केवल 2 दिनों में पूरा कर लिया। C अकेले यह कार्य कितने दिनों में पूरा कर सकता है?","eh":"C = 1/2 − 1/19 − 1/11 = 149/418 प्रति दिन, अतः C अकेला 418/149 = 2 120/149 दिन लेता है।"},{"s":"Mathematics","q":"A man makes a monthly payment equal to 25% of his monthly salary towards debt repayment. He spends 52% of the remaining salary and saves ₹288. His monthly salary (in ₹) is:","o":["811","816","800","888"],"a":2,"e":"0.75S × 0.48 = 0.36S = 288, so S = ₹800.","qh":"कोई व्यक्ति ऋण चुकाने के लिए अपने मासिक वेतन के 25% के बराबर मासिक भुगतान करता है। वह शेष वेतन का 52% खर्च करता है और ₹288 बचाता है। उसका मासिक वेतन (₹ में) ज्ञात कीजिए।","oh":["811","816","800","888"],"eh":"0.75S × 0.48 = 0.36S = 288, अतः S = ₹800।"},{"s":"Mathematics","q":"Which of the following numbers divides 74,75,79,723?","o":["13","9","8","11"],"a":3,"e":"747579723: (3 + 7 + 7 + 7 + 7) − (2 + 9 + 5 + 4) = 31 − 20 = 11, so it divides by 11.","qh":"निम्नलिखित में से कौन-सी संख्या, 74,75,79,723 को विभाजित करती है?","oh":["13","9","8","11"],"eh":"747579723: (3 + 7 + 7 + 7 + 7) − (2 + 9 + 5 + 4) = 31 − 20 = 11, अतः यह 11 से विभाज्य है।"},{"s":"Mathematics","q":"If the 6-digit number N42M47 is divisible by 11, then which of the options below can give a possible correct relation between M and N?","o":["M - N = 1","M + N = 5","M = N","M - N = -5"],"a":3,"e":"(N + 2 + 4) − (4 + M + 7) = N − M − 5 = 0, so M − N = −5.","qh":"यदि 6 अंकों की संख्या N42M47, 11 से विभाज्य है, तो नीचे दिए गए विकल्पों में से कौन-सा विकल्प, M और N के बीच संभावित सही संबंध दे सकता है?","oh":["M - N = 1","M + N = 5","M = N","M - N = -5"],"eh":"(N + 2 + 4) − (4 + M + 7) = N − M − 5 = 0, अतः M − N = −5।"},{"s":"Mathematics","q":"Find the value of [960 ÷ {28 + 5 × (7 − 3)}].","o":["29","20","23","15"],"a":1,"e":"28 + 5 × 4 = 48, and 960 ÷ 48 = 20.","qh":"[960 ÷ {28 + 5 × (7 − 3)}] का मान ज्ञात कीजिए।","oh":["29","20","23","15"],"eh":"28 + 5 × 4 = 48, और 960 ÷ 48 = 20।"},{"s":"Mathematics","q":"Five solid cubes, each of volume 216000 cm³, are joined end to end to form a cuboid. What is the lateral surface area (in cm²) of the cuboid?","o":["43045","43464","43245","43200"],"a":3,"e":"Side = 60 cm, so the cuboid is 300 × 60 × 60. LSA = 2(300 + 60) × 60 = 43200 cm².","qh":"पाँच ठोस घनों जिनमें से प्रत्येक का आयतन 216000 cm है, को सिरों से जोड़कर एक घनाभ बनाया 2 गया है। घनाभ का पार्श्व पृष्ठीय क्षेत्रफल (cm में) ज्ञात कीजिए।","oh":["43045","43464","43245","43200"],"eh":"भुजा = 60 cm, अतः घनाभ 300 × 60 × 60 है। पार्श्व पृष्ठीय क्षेत्रफल = 2(300 + 60) × 60 = 43200 cm²।"},{"s":"Mathematics","q":"The sum of two numbers is 66 and their L.C.M. is 400. What are the two numbers?","o":["21, 45","14, 52","16, 50","9, 57"],"a":2,"e":"16 + 50 = 66 and LCM(16, 50) = 400.","qh":"दो संख्याओं का योगफल 66 है और उनका लघुत्तम समापवर्त्य (L.C.M.) 400 है। वे दोनों संख्याएं ज्ञात कीजिए।","oh":["21, 45","14, 52","16, 50","9, 57"],"eh":"16 + 50 = 66 और LCM(16, 50) = 400।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 21 23 33 51 77 ?","o":["131","111","112","140"],"a":1,"e":"Differences 2, 10, 18, 26 (+8 each), then 34: 77 + 34 = 111.","qh":"दी गई श्रृंखला में प्रश्न-चिह्न (?) के स्थान पर क्या आना चाहिए? 21 23 33 51 77 ?","oh":["131","111","112","140"],"eh":"अंतर 2, 10, 18, 26 (प्रत्येक +8), फिर 34: 77 + 34 = 111।"},{"s":"General Intelligence and Reasoning","q":"W is the daughter of A. A is the brother of K. K is the wife of E. E is the father of S. How is W related to S?","o":["Mother's sister's son","Mother's sister's daughter","Mother's brother's daughter","Mother's brother's son"],"a":2,"e":"W's father A is the brother of K, who is S's mother. So W is S's mother's brother's daughter.","qh":"W, A की पुत्री है। A, K का भाई है। K, E की पत्नी है। E, S का पिता है। W का S से क्या संबंध है?","oh":["माता की बहन का पुत्र","माता की बहन की पुत्री","माता के भाई की पुत्री","माता के भाई का पुत्र"],"eh":"W का पिता A, K का भाई है, जो S की माता है। अतः W, S के मामा की पुत्री है।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-clusters are alike in a certain way and thus form a group. Which letter-cluster DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["UWS","MOJ","SUP","PRM"],"a":0,"e":"The others are +2, −5 (M→O→J). UWS is +2, −4.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, निम्नलिखित चार अक्षर-समूहों में से तीन एक निश्चित तरीके से एकसमान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह, उसमें व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["UWS","MOJ","SUP","PRM"],"eh":"अन्य में +2, −5 है (M→O→J)। UWS में +2, −4 है।"},{"s":"General Intelligence and Reasoning","q":"Pranay starts from Point A and drives 7 km towards the south. He then takes a left turn and drives 6 km, then turns left and drives 12 km. He then takes a left turn and drives 10 km. He takes a final left turn, drives 5 km and stops at Point P. How far (shortest distance) and in which direction should he drive in order to reach Point A again? (All turns are 90-degree turns only unless specified.)","o":["4 km to the east","4 km to the west","5 km to the west","5 km to the east"],"a":0,"e":"Net position: 4 km west and 0 km north of A, so he drives 4 km east.","qh":"प्रणय, बिंदु A से ड्राइव करना शुरू करता है और दक्षिण की ओर 7 km ड्राइव करता है। फिर वह बाएं मुड़ता है और 6 km ड्राइव करता है, फिर बाएं मुड़ता है और 12 km ड्राइव करता है। वह फिर से बाएं मुड़ता है और 10 km ड्राइव करता है। वह अंतिम बार बाएं मुड़ता है और 5 km ड्राइव करके बिंदु P पर रुक जाता है। बिंदु A पर वापस पहुँचने के लिए उसे कितनी दूरी (न्यूनतम दूरी) और किस दिशा में ड्राइव करना चाहिए? (जब तक निर्दिष्ट न किया जाए, सभी मोड़ केवल 90-डिग्री के मोड़ हैं।)","oh":["4 km, पूर्व की ओर","4 km, पश्चिम की ओर","5 km, पश्चिम की ओर","5 km, पूर्व की ओर"],"eh":"शुद्ध स्थिति: A से 4 km पश्चिम और 0 km उत्तर, अतः वह 4 km पूर्व जाता है।"},{"s":"General Intelligence and Reasoning","q":"DACB is related to FCED in a certain way based on the English alphabetical order. In the same way, YVXW is related to AXZY. To which of the given options is VSUT related, following the same logic?","o":["XUWV","XUVV","XTVV","XVVE"],"a":0,"e":"Each letter moves +2: V→X, S→U, U→W, T→V gives XUWV.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, एक निश्चित तरीके से DACB का संबंध FCED से है। उसी तरीके से, YVXW का संबंध AXZY से है। समान तर्क का अनुसरण करते हुए, VSUT का संबंध दिए गए विकल्पों में से किस विकल्प से है?","oh":["XUWV","XUVV","XTVV","XVVE"],"eh":"प्रत्येक अक्षर +2 खिसकता है: V→X, S→U, U→W, T→V, अतः XUWV।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-clusters are alike in a certain way and thus form a group. Which letter-cluster DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["RMH","DYT","AVO","IDY"],"a":2,"e":"The others are −5, −5 (R→M→H). AVO is −5, −7.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, निम्नलिखित चार अक्षर-समूहों में से तीन एक निश्चित तरीके से एकसमान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह, उसमें व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["RMH","DYT","AVO","IDY"],"eh":"अन्य में −5, −5 है (R→M→H)। AVO में −5, −7 है।"},{"s":"General Intelligence and Reasoning","q":"Based on the English alphabetical order, three of the following four letter-clusters are alike in a certain way and thus form a group. Which letter-cluster DOES NOT belong to that group? (Note: The odd one out is not based on the number of consonants/vowels or their position in the letter-cluster.)","o":["VZFM","PTZG","SWCI","IMSZ"],"a":2,"e":"The others are +4, +6, +7 (V→Z→F→M). SWCI ends with +6.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, निम्नलिखित चार अक्षर-समूहों में से तीन एक निश्चित तरीके से एकसमान हैं और इस प्रकार वे एक ग्रुप बनाते हैं। कौन-सा अक्षर-समूह उस ग्रुप से संबंधित नहीं है? (नोट: असंगत अक्षर-समूह, उसमें व्यंजनों/स्वरों की संख्या या उनकी स्थिति पर आधारित नहीं है।)","oh":["VZFM","PTZG","SWCI","IMSZ"],"eh":"अन्य में +4, +6, +7 है (V→Z→F→M)। SWCI के अंत में +6 है।"},{"s":"General Intelligence and Reasoning","q":"Seven boxes, N, O, T, F, A, R and M, are kept one over the other but not necessarily in the same order. M is kept immediately above A. N is kept immediately above O. Only T is kept above F. Only two boxes are kept above M. N is not kept at third position from the bottom. How many boxes are kept between R and T?","o":["Three","One","Zero","Two"],"a":0,"e":"Top to bottom: T, F, M, A, R, N, O. Three boxes are between R and T.","qh":"सात बॉक्स, N, O, T, F, A, R और M, एक के ऊपर एक रखे गए हैं, लेकिन जरूरी नहीं कि वे इसी क्रम में हों। M को A के ठीक ऊपर रखा गया है। N को O के ठीक ऊपर रखा गया है। F के ऊपर केवल T को रखा गया है। M के ऊपर केवल दो बॉक्स रखे गए हैं। N को नीचे से तीसरे स्थान पर नहीं रखा गया है। R और T के बीच कितने बॉक्स रखे गए हैं?","oh":["तीन","एक","एक भी नहीं","दो"],"eh":"ऊपर से नीचे: T, F, M, A, R, N, O। R और T के बीच तीन बॉक्स हैं।"},{"s":"General Intelligence and Reasoning","q":"If 1 is added to each odd digit and 2 is subtracted from each even digit in the number 7856413, what will be the sum of the digits which are third from the left and third from the right in the new number thus formed?","o":["6","10","12","8"],"a":3,"e":"7856413 becomes 8664224. 6 + 2 = 8.","qh":"यदि संख्या 7856413 के प्रत्येक विषम अंक में 1 जोड़ा जाए और प्रत्येक सम अंक में से 2 घटाया जाए, तो इस प्रकार बनी नई संख्या में बाएं से तीसरे और दाएं से तीसरे अंक का योगफल कितना होगा?","oh":["6","10","12","8"],"eh":"7856413, 8664224 बन जाता है। 6 + 2 = 8।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 73 76 81 90 107 ?","o":["139","123","155","140"],"a":3,"e":"Differences 3, 5, 9, 17 (doubling minus 1), then 33: 107 + 33 = 140.","qh":"दी गई श्रृंखला में प्रश्न-चिन्ह (?) के स्थान पर क्या आना चाहिए? 73 76 81 90 107 ?","oh":["139","123","155","140"],"eh":"अंतर 3, 5, 9, 17 (दोगुना घटा 1), फिर 33: 107 + 33 = 140।"},{"s":"General Intelligence and Reasoning","q":"In a row of 22 students facing north, Mayank is 15th from the left end. If Payal is 7th to the right of Mayank, what is Payal's position from the right end of the line?","o":["1st","3rd","4th","2nd"],"a":0,"e":"Payal is 15 + 7 = 22nd from the left, which is 1st from the right.","qh":"उत्तर दिशा की ओर अभिमुख होकर बैठे 22 छात्रों की एक पंक्ति में, मयंक बाएं छोर से 15वें स्थान पर है। वें यदि पायल, मयंक के दाएं से 7 स्थान पर है, तो पंक्ति के दाएं छोर से पायल का स्थान कौन-सा है?","eh":"पायल बाएँ से 15 + 7 = 22वें स्थान पर है, जो दाएँ से पहला है।"},{"s":"General Intelligence and Reasoning","q":"Refer to the following number and symbol series and answer the question that follows. Counting to be done from left to right only. (Left) / 8 5 2 1 1 4 < $ 2 & 8 # 7 5 & 3 + 1 6 ^ (Right) How many such numbers are there that are immediately preceded by a symbol and also immediately followed by another number?","o":["Four","One","Three","Two"],"a":2,"e":"Numbers preceded by a symbol and followed by a number: /8-5, #7-5 and +1-6. That makes three.","qh":"निम्नलिखित संख्या और प्रतीक श्रृंखला का संदर्भ लीजिए और नीचे दिए गए प्रश्न का उत्तर दीजिए। गिनती केवल बाएं से दाएं की जानी चाहिए। (बाएं) / 8 5 2 1 1 4 < $ 2 & 8 # 7 5 & 3 + 1 6 ^ (दाएं) ऐसी कितनी संख्याएँ हैं जिनके ठीक पहले एक प्रतीक है और ठीक बाद में एक अन्य संख्या भी है?","oh":["चार","एक","तीन","दो"],"eh":"वे संख्याएँ जिनसे पहले प्रतीक और बाद में संख्या है: /8-5, #7-5 और +1-6। कुल तीन।"},{"s":"General Intelligence and Reasoning","q":"Refer to the following number and symbol series and answer the question that follows. Counting to be done from left to right only. (Left) 2 & % 4 6 Ω * 7 $ £ 8 & 1 % @ 5 3 # * 9 (Right) How many such symbols are there, each of which is immediately preceded by a number and also immediately followed by another number?","o":["None","Two","One","More than two"],"a":2,"e":"Only & (in 8 & 1) has numbers on both sides. That makes one.","qh":"निम्नलिखित संख्या और प्रतीक शृंखला का संदर्भ लीजिए तथा नीचे दिए गए प्रश्न का उत्तर दीजिए। गिनती केवल बाएँ से दाएँ की जानी चाहिए। (बाएँ) 2 & % 4 6 Ω * 7 $ £ 8 & 1 % @ 5 3 # * 9 (दाएँ) ऐसे कितने प्रतीक हैं, जिनमें से प्रत्येक के ठीक पहले एक संख्या और ठीक बाद एक अन्य संख्या है?","oh":["एक भी नहीं","दो से अधिक","एक","दो"],"eh":"केवल & (8 & 1 में) के दोनों ओर संख्याएँ हैं। कुल एक।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of ? in the given series based on the English alphabetical order? ELY FNX GPW HRV ?","o":["HYV","HGU","IUV","ITU"],"a":3,"e":"1st letter +1, 2nd +2, 3rd −1: H→I, R→T, V→U gives ITU.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर, दी गई शृंखला में प्रश्न-चिह्न (?) के स्थान पर क्या आना चाहिए? ELY FNX GPW HRV ?","oh":["HYV","HGU","IUV","ITU"],"eh":"पहला अक्षर +1, दूसरा +2, तीसरा −1: H→I, R→T, V→U, अतः ITU।"},{"s":"General Intelligence and Reasoning","q":"What should come in place of the question mark (?) in the given series? 819 829 830 840 841 851 852 ?","o":["853","854","862","861"],"a":2,"e":"Add +10 and +1 alternately: 852 + 10 = 862.","qh":"दी गई श्रृंखला में प्रश्न-चिन्ह (?) के स्थान पर क्या आएगा? 819 829 830 840 841 851 852 ?","oh":["853","854","862","861"],"eh":"बारी-बारी से +10 और +1 जोड़ें: 852 + 10 = 862।"},{"s":"General Intelligence and Reasoning","q":"In a certain code language, ‘TEMP’ is coded as ‘3129’ and ‘ITEM’ is coded as ‘1396’. What is the code for ‘I’ in the given code language?","o":["1","3","9","6"],"a":3,"e":"T, E, M share 3, 1, 9, so I = 6.","qh":"एक निश्चित कूट भाषा में, ‘TEMP’ को ‘3129’ तथा ‘ITEM’ को ‘1396’ के रूप में कूटबद्ध किया जाता है। दी गई कूट भाषा में ‘I’ के लिए कूट क्या है?","oh":["1","3","9","6"],"eh":"T, E, M के कूट 3, 1, 9 उभयनिष्ठ हैं, अतः I = 6।"},{"s":"General Intelligence and Reasoning","q":"Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusion(s) logically follow(s) from the statements. Statements: All magnets are rocks. All rocks are soils. Conclusions: (I) Some soils are rocks. (II) All magnets are soils.","o":["Neither conclusion (I) nor (II) follows.","Only conclusion (II) follows.","Only conclusion (I) follows.","Both conclusions (I) and (II) follow."],"a":3,"e":"Magnets ⊂ rocks ⊂ soils, so both conclusions follow.","qh":"दिए गए कथनों और निष्कर्षों को ध्यानपूर्वक पढ़ें। यह मानते हुए कि कथनों में दी गई जानकारी सत्य है, भले ही वह सामान्यतः ज्ञात तथ्यों से भिन्न प्रतीत होती हो, तय करें कि दिए गए निष्कर्षों में से कौन-से निष्कर्ष कथनों का तार्किक रूप से अनुसरण करते हैं। कथन: सभी चुम्बक, चट्टानें हैं। सभी चट्टानें, मिट्टी हैं। निष्कर्ष: (I) कुछ मिट्टी, चट्टानें हैं। (II) सभी चुम्बक, मिट्टी हैं।","oh":["न तो निष्कर्ष (I) और न ही (II) अनुसरण करता है।","केवल निष्कर्ष (II) अनुसरण करता है।","केवल निष्कर्ष (I) अनुसरण करता है।","निष्कर्ष (I) और (II) दोनों अनुसरण करते हैं।"],"eh":"चुंबक ⊂ चट्टानें ⊂ मृदा, अतः दोनों निष्कर्ष अनुसरण करते हैं।"},{"s":"General Intelligence and Reasoning","q":"Read the given statement(s) and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusion(s) logically follow(s) from the statement(s). Statements: Some Beetroots are Radishes. Some Radishes are Onions. Conclusions: I. Some Beetroots are Onions. II. No Beetroots are Onions.","o":["Only conclusion (I) follows.","Only conclusion (II) follows.","Both conclusions (I) and (II) follow.","Neither conclusion (I) nor (II) follows."],"a":3,"e":"With two 'some' statements nothing definite follows, so neither conclusion does.","qh":"दिए गए कथनों और निष्कर्षों को ध्यान से पढ़ें। यह मानते हुए कि कथनों में दी गई जानकारी सत्य है, भले ही वह सामान्य रूप से ज्ञात तथ्यों से भिन्न प्रतीत होती हो, तय करें कि दिए गए निष्कर्षों में से कौन-से निष्कर्ष कथनों का तार्किक रूप से अनुसरण करते हैं। कथन: कुछ चुकंदर, मूली हैं। कुछ मूली, प्याज हैं। निष्कर्ष: I. कुछ चुकंदर, प्याज हैं। II. कोई चुकंदर, प्याज नहीं है।","oh":["केवल निष्कर्ष (I) अनुसरण करता है।","केवल निष्कर्ष (II) अनुसरण करता है।","निष्कर्ष (I) और (II) दोनों अनुसरण करते हैं।","न तो निष्कर्ष (I) और न ही (II) अनुसरण करता है।"],"eh":"दो 'कुछ' कथनों से कुछ भी निश्चित नहीं निकलता, अतः कोई भी निष्कर्ष अनुसरण नहीं करता।"},{"s":"General Intelligence and Reasoning","q":"Which of the following letter-number clusters will replace the question mark (?) in the given series to make it logically complete? TKF 4, SJE 8, RID 12, QHC 16, ?","o":["OGB 20","PFA 18","OFA 18","PGB 20"],"a":3,"e":"Each letter moves −1 (Q→P, H→G, C→B) and the number +4, giving PGB 20.","qh":"निम्नलिखित में से कौन-सा अक्षर-संख्या समूह दी गई श्रृंखला को तार्किक रूप से पूर्ण बनाने के लिए प्रश्न- चिह्न (?) के स्थान पर आएगा? TKF 4, SJE 8, RID 12, QHC 16, ?","oh":["OGB 20","PFA 18","OFA 18","PGB 20"],"eh":"प्रत्येक अक्षर −1 खिसकता है (Q→P, H→G, C→B) और संख्या +4, अतः PGB 20।"},{"s":"General Intelligence and Reasoning","q":"In the following number-pairs, the second number is obtained by applying certain mathematical operation(s) to the first number. Select the number-pair in which the numbers are related in the same way as are the numbers of the following pairs. (NOTE: Operations should be performed on the whole numbers, without breaking down the numbers into their constituent digits. E.g. 13 – Operations on 13 such as adding to/subtracting from/multiplying with 13 can be performed. Breaking down 13 into 1 and 3 and then performing mathematical operations on 1 and 3 is not allowed.) 12, 134 9, 71","o":["15, 235","13, 170","16, 246","11, 130"],"a":2,"e":"2nd = 1st² − 10: 12² − 10 = 134, 9² − 10 = 71, 16² − 10 = 246.","qh":"निम्नलिखित संख्या-युग्मों में, पहली संख्या पर कुछ गणितीय संक्रियाएँ करके दूसरी संख्या प्राप्त की जाती है। उस संख्या-युग्म का चयन कीजिए जिसमें संख्याएँ उसी प्रकार संबंधित हैं जिस प्रकार निम्नलिखित युग्मों की संख्याएँ संबंधित हैं। (नोट: संख्याओं को उनके घटक अंकों में तोड़े बिना, संक्रियाएँ पूर्ण संख्याओं पर की जानी चाहिए। उदाहरण के लिए 13 को लीजिए - 13 पर संक्रियाएँ जैसे कि 13 में जोड़ना/घटाना/गुणा करना आदि किया जा सकता है। 13 को 1 एवं 3 में तोड़ना और फिर 1 एवं 3 पर गणितीय संक्रियाएँ करने की अनुमति नहीं है।) 12, 134 9, 71","oh":["15, 235","13, 170","16, 246","11, 130"],"eh":"दूसरी = पहली² − 10: 12² − 10 = 134, 9² − 10 = 71, 16² − 10 = 246।"},{"s":"General Intelligence and Reasoning","q":"211 people are standing in a row facing north. Mr. Maxi is 9th from the left end while Mr. Han is 91st from the right end. How many people are there between Mr. Maxi and Mr. Han?","o":["112","111","109","110"],"a":1,"e":"Han is 211 − 91 + 1 = 121st from the left, so between them = 121 − 9 − 1 = 111.","qh":"उत्तर की ओर अभिमुख होकर खड़े 211 व्यक्तियों की एक पंक्ति में मिस्टर मैक्सी, बाएं छोर से 9वें स्थान पर हैं जबकि मिस्टर हान, दाएं छोर से 91वें स्थान पर हैं। मिस्टर मैक्सी और मिस्टर हान के बीच कितने व्यक्ति हैं?","oh":["112","111","109","110"],"eh":"Han बाएँ से 211 − 91 + 1 = 121वाँ है, अतः उनके बीच = 121 − 9 − 1 = 111।"},{"s":"General Intelligence and Reasoning","q":"SKEA is related to PGBW in a certain way based on the English alphabetical order. In the same way, GUSK is related to DQPG. To which of the given options is XIJY related, following the same logic?","o":["PPOI","UGEU","UIOP","UEGU"],"a":3,"e":"Pattern −3, −4, −3, −4: X→U, I→E, J→G, Y→U gives UEGU.","qh":"अंग्रेजी वर्णमाला क्रम पर आधारित, एक निश्चित तरीके से SKEA का संबंध PGBW से है। उसी तरीके से, GUSK का संबंध DQPG से है। समान तर्क का अनुसरण करते हुए, दिए गए विकल्पों में से XIJY का संबंध किससे है?","oh":["PPOI","UGEU","UIOP","UEGU"],"eh":"पैटर्न −3, −4, −3, −4: X→U, I→E, J→G, Y→U, अतः UEGU।"},{"s":"General Intelligence and Reasoning","q":"What will come in the place of the question mark (?) in the following equation, if ‘+’ and ‘−’ are interchanged and ‘×’ and ‘÷’ are interchanged? 26 × 4 ÷ 8 − 15 + 6 = ?","o":["62","59","61","60"],"a":2,"e":"Becomes 26 ÷ 4 × 8 + 15 − 6 = 52 + 15 − 6 = 61.","qh":"यदि ‘+’ और ‘−’ को परस्पर बदल दिया जाए तथा ‘×’ और ‘÷’ को परस्पर बदल दिया जाए, तो निम्नलिखित समीकरण में प्रश्न चिन्ह (?) के स्थान पर क्या आएगा? 26 × 4 ÷ 8 − 15 + 6 = ?","oh":["62","59","61","60"],"eh":"यह 26 ÷ 4 × 8 + 15 − 6 = 52 + 15 − 6 = 61 बन जाता है।"},{"s":"General Intelligence and Reasoning","q":"Seven people A, B, C, D, E, F and G are sitting in a row, facing the north. Only one person sits to the right of B. E sits third from the left end of the row. G is the immediate neighbour of F and B. C sits to the immediate left of A. How many people sit to the left of D?","o":["Four","Three","Six","Five"],"a":2,"e":"The order is C, A, E, F, G, B, D. Six people are to the left of D.","qh":"सात व्यक्ति A, B, C, D, E, F और G उत्तर की ओर अभिमुख होकर एक पंक्ति में बैठे हैं। B के दाएं केवल एक व्यक्ति बैठा है। E पंक्ति के बाएं छोर से तीसरे स्थान पर बैठा है। F और B का निकटतम पड़ोसी G है। C, A के ठीक बाएं पड़ोस में बैठा है। D के बाएं कितने व्यक्ति बैठे हैं?","oh":["चार","तीन","छह","पाँच"],"eh":"क्रम C, A, E, F, G, B, D है। D के बाएँ छह व्यक्ति हैं।"},{"s":"General Intelligence and Reasoning","q":"Satheesh starts from his home and drives 5 km towards north. He then takes a left turn, drives 6 km, turns left, and drives 4 km. He then takes a right turn and drives 5 km and turns right, then drives 3 km to reach his office. In which direction is the office with respect to his home? (Note: All turns are 90° turns only, unless specified.)","o":["North-west","North","South","West"],"a":0,"e":"Net position: 11 km west and 4 km north of home, so the office is north-west.","qh":"सतीश अपने घर से यात्रा शुरू करके उत्तर दिशा की ओर 5 km ड्राइव करता है। फिर वह बाएं मुड़ता है, 6 km ड्राइव करता है, बाएं मुड़ता है और 4 km ड्राइव करता है। फिर वह दाएं मुड़ता है और 5 km ड्राइव करता है और दाएं मुड़ता है, फिर 3 km ड्राइव करके अपने कार्यालय पहुंचता है। उसके घर के सापेक्ष कार्यालय किस दिशा में है? (जब तक अन्यथा विनिर्दिष्ट न किया गया हो, सभी मोड़ केवल 90° के मोड़ हैं )","oh":["उत्तर-पश्चिम","उत्तर","दक्षिण","पश्चिम"],"eh":"शुद्ध स्थिति: घर से 11 km पश्चिम और 4 km उत्तर, अतः कार्यालय उत्तर-पश्चिम में है।"},{"s":"General Intelligence and Reasoning","q":"In a certain code language, ‘LIKE’ is coded as ‘7029’ and ‘KAIL’ is coded as ‘1279’. What is the code for ‘A’ in the given code language?","o":["1","2","9","7"],"a":0,"e":"L, I, K share 7, 2, 9, so A = 1.","qh":"एक निश्चित कूट भाषा में, ‘LIKE’ को ‘7029’ और ‘KAIL’ को ‘1279’ के रूप में कूटबद्ध किया जाता है। दी गई कूट भाषा में ‘A’ का कूट क्या होगा?","oh":["1","2","9","7"],"eh":"L, I, K के कूट 7, 2, 9 उभयनिष्ठ हैं, अतः A = 1।"},{"s":"General Intelligence and Reasoning","q":"Five people, A, B, C, D and E are sitting in a straight line, facing North. B is sitting to the extreme left end. Only two people are sitting between D and B. E is seated second to the right of B. A is not an immediate neighbour of E. How many people are sitting to the right of C?","o":["Three","One","Zero","Two"],"a":0,"e":"The order is B, C, E, D, A. Three people are to the right of C.","qh":"पांच व्यक्ति, A, B, C, D और E, एक सीधी पंक्ति में उत्तर दिशा की ओर अभिमुख होकर बैठे हैं। बाएं छोर पर B बैठा है। D और B के बीच केवल दो व्यक्ति बैठे हैं। B के दाएं दूसरे स्थान पर E बैठा है। A, E का निकटतम पड़ोसी नहीं है। C के दाएं कितने व्यक्ति बैठे हैं?","oh":["तीन","एक","एक भी नहीं","दो"],"eh":"क्रम B, C, E, D, A है। C के दाएँ तीन व्यक्ति हैं।"},{"s":"General Intelligence and Reasoning","q":"CROWD is related to HWTBI in a certain way based on the English alphabetical order. In the same way, DRAWN is related to IWFBS. To which of the given options is BRUSH related, following the same logic?","o":["GWZXM","FVYWL","GWZYM","HXAYN"],"a":0,"e":"Each letter moves +5: B→G, R→W, U→Z, S→X, H→M gives GWZXM.","qh":"अंग्रेजी वर्णमाला क्रम के आधार पर एक निश्चित तरीके से CROWD का संबंध HWTBI से है। उसी तरह DRAWN का संबंध IWFBS से है। समान तर्क का अनुसरण करते हुए, BRUSH का दिए गए विकल्पों में से किससे संबंध है?","oh":["GWZXM","FVYWL","GWZYM","HXAYN"],"eh":"प्रत्येक अक्षर +5 खिसकता है: B→G, R→W, U→Z, S→X, H→M, अतः GWZXM।"},{"s":"General Intelligence and Reasoning","q":"Each of the digits in the number 9231475 is arranged in ascending order from left to right. The position(s) of how many digits will remain unchanged as compared to that in the original number?","o":["One","None","Three","Two"],"a":2,"e":"9231475 becomes 1234579. 2, 3 and 7 keep their places, so three.","qh":"संख्या 9231475 में प्रत्येक अंक को बाएँ से दाएँ आरोही क्रम में व्यवस्थित किया जाता है। मूल संख्या की तुलना में कितने अंकों का स्थान अपरिवर्तित रहेगा?","oh":["एक","एक भी नहीं","तीन","दो"],"eh":"9231475, 1234579 बन जाता है। 2, 3 और 7 अपने स्थान पर रहते हैं, अतः तीन।"},{"s":"General Intelligence and Reasoning","q":"If 1 is added to each even digit and 3 is subtracted from each odd digit in the number 943372856, what will be difference between the highest and lowest digits thus formed?","o":["9","7","8","6"],"a":0,"e":"943372856 becomes 650043927. Highest 9 − lowest 0 = 9.","qh":"यदि संख्या 943372856 के प्रत्येक सम अंक में 1 जोड़ा जाए और प्रत्येक विषम अंक में से 3 घटाया जाए, तो इस प्रकार बने सबसे बड़े अंक और सबसे छोटे अंक के बीच कितना अंतर होगा?","oh":["9","7","8","6"],"eh":"943372856, 650043927 बन जाता है। सबसे बड़ा 9 − सबसे छोटा 0 = 9।"}]});
